mapper.select:
SELECT request_id,thread_id,turn_id,tool_call_id,plan_revision_id,run_id,goal_id,idempotency_key,
       questions_json,status,answers_json,revision,created_at,updated_at
FROM interaction_requests WHERE thread_id=#{threadId} AND request_id=#{requestId}

mapper.update:
UPDATE interaction_requests SET answers_json=#{answersJson},status=#{status},revision=revision+1,
       idempotency_key=#{idempotencyKey},updated_at=#{occurredAt}
WHERE thread_id=#{threadId} AND request_id=#{requestId} AND status='PENDING' AND revision=#{expectedRevision}

UPDATE interaction_requests SET status=#{status},revision=revision+1,idempotency_key=#{idempotencyKey},
       updated_at=#{occurredAt}
WHERE thread_id=#{threadId} AND request_id=#{requestId} AND status='PENDING' AND revision=#{expectedRevision}

mapper.select:
SELECT event_sequence,thread_id,request_id,request_revision,kind,occurred_at
FROM interaction_events WHERE thread_id=#{threadId} AND event_sequence>#{afterSequence}
ORDER BY event_sequence ASC
